package com.nigson.acceptance.carrier;

import java.time.*;
import java.net.*;
import java.net.http.*;
import java.util.*;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.acceptance.pricing.PricingFixture;
import com.nigson.acceptance.provider.JobHttpAcceptance;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import static org.assertj.core.api.Assertions.*;

/** Actual BFF/JDBC sessions, current party authority, KMS SDK signing and scoped workload JWT HTTP. */
public final class CarrierDeliveryHttpAcceptance {
 private CarrierDeliveryHttpAcceptance(){}
 public static void configure(Map<String,Object> properties){if(System.getenv("NIGSON_TEST_CARRIER")==null)return;properties.put("NIGSON_CARRIER_QUOTES_ENABLED","true");properties.put("NIGSON_PRICING_CHECKOUT_ENABLED","true");properties.put("NIGSON_PRICING_PROVIDER_MODE","MOCK");properties.put("NIGSON_PRICING_PAYMENT_APPROVAL","SYNTHETIC_PAYMENT_NOT_QUALIFIED");properties.put("NIGSON_PRICING_CARRIER_APPROVAL","SYNTHETIC_CARRIER_NOT_QUALIFIED");properties.put("NIGSON_PRICING_PROVIDER_APPROVAL_UNTIL",Instant.now().plusSeconds(600).toString());properties.put("NIGSON_FULFILLMENT_ENABLED","true");properties.put("NIGSON_FULFILLMENT_MODE","MOCK");properties.put("NIGSON_FULFILLMENT_APPROVAL","synthetic-offline-approval");properties.put("NIGSON_FULFILLMENT_APPROVAL_UNTIL",Instant.now().plusSeconds(600).toString());properties.put("NIGSON_CARRIER_ORIGIN_JSON","{\"recipient\":\"Synthetic Shipper\",\"phone\":\"+2348000000001\",\"line1\":\"Synthetic Origin\",\"line2\":null,\"city\":\"Lagos\",\"region\":\"LA\",\"postalCode\":null,\"countryCode\":\"NG\"}");}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base,JobHttpAcceptance.Fixture upstream)throws Exception{
  if(System.getenv("NIGSON_TEST_CARRIER")==null)return;var sessions=app.getBean(JdbcSessionTrust.class);String session=null;
  try(var f=new PricingFixture(app.getBean(JdbcTemplate.class),app.getBean(org.springframework.transaction.PlatformTransactionManager.class))){f.retail();f.jdbc.update("DELETE FROM commerce.carrier_quote WHERE cart_id=?",f.cart);f.jdbc.update("UPDATE commerce.party SET identity_issuer=? WHERE id=?",upstream.issuer,f.customer.party());var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String csrf=JdbcSessionTrust.opaque();session=sessions.authenticate(flow.sessionId(),new SessionRecord(1,f.customer.party(),upstream.issuer,f.customer.party().toString(),Instant.now(),Instant.now(),"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),csrf,SessionRecord.TokenState.READY));String cookie="__Host-nigson-session="+session,path=base+"/api/v1/carts/"+f.cart+"/delivery-quotes",body=EventCodec.JSON.writeValueAsString(Map.of("addressId",f.address));int effects=upstream.carrierEffects.get(),signs=upstream.signs.get();
   assertThat(send(http,HttpRequest.newBuilder(URI.create(path)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body))).statusCode()).isEqualTo(401);assertThat(send(http,mutation(path,cookie,"wrong",body,"csrf","\"0\"")).statusCode()).isEqualTo(401);assertThat(send(http,mutation(path,cookie,csrf,body,"version",null)).statusCode()).isEqualTo(400);assertThat(send(http,mutation(path,cookie,csrf,body,"stale","\"1\"")).statusCode()).isEqualTo(412);assertThat(send(http,mutation(path,cookie,csrf,body.replace("}",",\"amount\":\"0\"}"),"injected","\"0\"")).statusCode()).isEqualTo(400);assertThat(upstream.carrierEffects.get()).isEqualTo(effects);assertThat(upstream.signs.get()).isEqualTo(signs);
   String key=UUID.randomUUID().toString();var response=send(http,mutation(path,cookie,csrf,body,key,"\"0\""));assertThat(response.statusCode()).as("delivery quote response: %s",response.body()).isEqualTo(201);assertThat(response.headers().firstValue("Cache-Control")).contains("no-store");var dto=EventCodec.JSON.readTree(response.body());assertThat(dto.propertyNames()).containsExactlyInAnyOrder("id","provider","serviceCode","currency","deliveryAmount","expiresAt","cartVersion","mode");assertThat(dto.path("deliveryAmount").asString()).isEqualTo("1234.56");assertThat(dto.path("mode").asString()).isEqualTo("MOCK");assertThat(upstream.carrierEffects.get()).isEqualTo(effects+1);int acceptedSigns=upstream.signs.get();assertThat(acceptedSigns).isEqualTo(signs+1);assertThat(send(http,mutation(path,cookie,csrf,body,key,"\"0\"")).body()).isEqualTo(response.body());assertThat(upstream.signs.get()).isEqualTo(acceptedSigns);assertThat(upstream.carrierEffects.get()).isEqualTo(effects+1);f.jdbc.update("UPDATE commerce.party SET status='SUSPENDED' WHERE id=?",f.customer.party());assertThat(send(http,mutation(path,cookie,csrf,body,key,"\"0\"")).statusCode()).isIn(401,403);assertThat(upstream.carrierEffects.get()).isEqualTo(effects+1);
  }finally{if(session!=null)sessions.logout(session);}
 }
 private static HttpRequest.Builder mutation(String path,String cookie,String csrf,String body,String key,String version){var request=HttpRequest.newBuilder(URI.create(path)).header("Cookie",cookie).header("X-CSRF-TOKEN",csrf).header("Idempotency-Key",key).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body));if(version!=null)request.header("If-Match",version);return request;}
 private static HttpResponse<String> send(HttpClient http,HttpRequest.Builder request)throws Exception{return http.send(request.timeout(Duration.ofSeconds(15)).build(),HttpResponse.BodyHandlers.ofString());}
}
